// The Data page host (the-data-graph-a-global-third-pillar, epic #3604) — renders the Data pillar FROM
// THE GRAPH. Mirrors `SoundsGraphHost`: like Sounds, this is not a rail Workspace but a tab the planner
// Screen mounts, and nothing else about the recipe changes.
//
// IT REGISTERS NOTHING, which is why it is the shortest host in the set. Every other page host calls a
// `register<X>Platform()` at module load because its page composes feature-local libs the loader has to
// resolve. `DataGraphPage` imports only shared/ui primitives and `@/shared/lib/core/bsc` — all of them
// already in `appModules`' PLATFORM — so there is no feature surface to inject and no
// `features/data/graphPlatform.ts` to write. Adding an empty one would be inventory, not wiring.
//
// There is no stylesheet either: the page styles entirely through the shared primitives, so the usual
// "the host owns the CSS the loader cannot import" clause does not apply.
import { GraphComponent } from "@/shared/lib/runtime/GraphComponent";
import { GraphPageFallback } from "@/shared/lib/runtime/GraphPageFallback";

export function DataGraphHost() {
  return <GraphComponent id="datagraphpage" fallback={<GraphPageFallback page="Data" icon="⛁" />} />;
}
